package br.com.onda;
import android.app.ActivityManager;import android.content.*;import android.net.*;import android.os.*;import java.io.*;import java.net.*;import java.security.MessageDigest;import java.util.*;
/** Only optional model downloads use network. Prompts and generated content never leave the device. */
final class LocalAiModels {
 enum Model{
  LITE("Leve • 105 MB","bartowski/SmolLM2-135M-Instruct-GGUF","09816acd5d99df7be770d85ea30822623dab342c","SmolLM2-135M-Instruct-Q4_K_M.gguf",105454432L,"2e8040ceae7815abe0dcb3540b9995eaa1fa0d2ca9e797d0a635ae4433c68c2d"),
  BALANCED("Completo • 1,1 GB","Qwen/Qwen2.5-1.5B-Instruct-GGUF","91cad51170dc346986eccefdc2dd33a9da36ead9","qwen2.5-1.5b-instruct-q4_k_m.gguf",1117320736L,"6a1a2eb6d15622bf3c96857206351ba97e1af16c30d7a74ee38970e434e9407e");
  final String label,repo,revision,file,sha;final long bytes;Model(String l,String r,String rev,String f,long b,String hash){label=l;repo=r;revision=rev;file=f;bytes=b;sha=hash;}
 }
 interface Progress{void changed(long bytes,long total);}
 @androidx.annotation.Keep static final class Cancel{private volatile boolean cancelled;private volatile HttpURLConnection connection;void check()throws InterruptedIOException{if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Operação interrompida");}void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}@androidx.annotation.Keep public boolean cancelled(){return cancelled;}}
 static File path(Context c,Model m){return new File(new File(c.getFilesDir(),"ai-models"),m.file);}
 static boolean installed(Context c,Model m){File f=path(c,m);return f.isFile()&&f.length()==m.bytes;}
 static Model suggested(Context c){ActivityManager.MemoryInfo info=memory(c);return android.os.Process.is64Bit()&&info.totalMem>=3L*1024*1024*1024&&info.availMem>Model.BALANCED.bytes+160L*1024*1024?Model.BALANCED:Model.LITE;}
 private static ActivityManager.MemoryInfo memory(Context c){ActivityManager.MemoryInfo info=new ActivityManager.MemoryInfo();((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(info);return info;}
 static void checkMemory(Context c,Model m)throws IOException{if(m==Model.BALANCED&&!android.os.Process.is64Bit())throw new IOException("O modelo Completo exige um aparelho de 64 bits. Fotos, cartões, tarefas e o modelo Leve continuam disponíveis.");ActivityManager.MemoryInfo info=memory(c);if(info.lowMemory||info.availMem<m.bytes+160L*1024*1024)throw new IOException("Pouca memória livre para este modelo. Feche outros apps ou escolha o modelo Leve. As tarefas do Onda continuam disponíveis.");if(Build.VERSION.SDK_INT>=29){PowerManager power=(PowerManager)c.getSystemService(Context.POWER_SERVICE);if(power!=null&&power.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE)throw new IOException("O celular está quente. Aguarde esfriar antes de usar a IA.");}}
 private static void wifi(Context c)throws IOException{ConnectivityManager manager=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities network=manager==null?null:manager.getNetworkCapabilities(manager.getActiveNetwork());if(network==null||!network.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))throw new IOException("Conecte ao Wi-Fi ou desative Somente Wi-Fi para este download.");}
 static File verified(Context c,Model m,Cancel cancel)throws Exception{File f=path(c,m);if(!installed(c,m))throw new IOException("Baixe o modelo escolhido primeiro.");SharedPreferences cache=c.getSharedPreferences("ai-model-checks",0);String stamp=f.lastModified()+":"+f.length();if(!stamp.equals(cache.getString(m.file,""))){if(!hash(f,cancel).equals(m.sha))throw new IOException("O modelo está incompleto ou alterado. Remova e baixe novamente.");cache.edit().putString(m.file,stamp).apply();}cancel.check();return f;}
 static File download(Context c,Model m,boolean onlyWifi,Cancel cancel,Progress progress)throws Exception{
  if(m==Model.BALANCED&&!android.os.Process.is64Bit())throw new IOException("O modelo Completo exige um aparelho de 64 bits. Use o modelo Leve para mensagens simples.");
  File target=path(c,m),folder=target.getParentFile();if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("Não foi possível criar a pasta dos modelos.");if(installed(c,m))return verified(c,m,cancel);if(onlyWifi)wifi(c);cancel.check();File part=new File(folder,m.file+".part");long offset=part.isFile()?part.length():0;if(offset>=m.bytes){part.delete();offset=0;}if(folder.getUsableSpace()<m.bytes-offset+32L*1024*1024)throw new IOException("Libere espaço no celular para baixar o modelo.");
  HttpURLConnection connection=(HttpURLConnection)new URL("https://huggingface.co/"+m.repo+"/resolve/"+m.revision+"/"+m.file).openConnection();cancel.connection=connection;connection.setConnectTimeout(15000);connection.setReadTimeout(15000);connection.setRequestProperty("User-Agent","Onda-Local-AI");if(offset>0)connection.setRequestProperty("Range","bytes="+offset+"-");
  try{cancel.check();int status=connection.getResponseCode();if(status!=200&&status!=206)throw new IOException("Não foi possível baixar o modelo agora. Tente novamente mais tarde.");if(status==206){String range=connection.getHeaderField("Content-Range");if(range==null||!range.startsWith("bytes "+offset+"-"))throw new IOException("O servidor não confirmou a retomada do download.");}else offset=0;long count=offset,last=0,nextWifi=count+1048576;try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(part,offset>0)){byte[] block=new byte[32768];int n;while((n=in.read(block))!=-1){cancel.check();count+=n;if(count>m.bytes){part.delete();throw new IOException("Tamanho do modelo inválido.");}out.write(block,0,n);if(onlyWifi&&count>=nextWifi){wifi(c);nextWifi=count+1048576;}long now=System.nanoTime();if(now-last>400000000){last=now;progress.changed(count,m.bytes);}}}cancel.check();if(count!=m.bytes)throw new IOException("Download incompleto. Toque em Baixar para retomar.");if(!hash(part,cancel).equals(m.sha)){part.delete();throw new IOException("O modelo não passou na verificação. Baixe novamente.");}if(target.exists()&&!target.delete())throw new IOException("Não foi possível substituir o modelo.");if(!part.renameTo(target))throw new IOException("Não foi possível salvar o modelo.");c.getSharedPreferences("ai-model-checks",0).edit().putString(m.file,target.lastModified()+":"+target.length()).apply();return target;
  }finally{connection.disconnect();cancel.connection=null;}
 }
 private static String hash(File file,Cancel cancel)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] data=new byte[65536];int n;while((n=in.read(data))!=-1){cancel.check();digest.update(data,0,n);}}StringBuilder out=new StringBuilder();for(byte value:digest.digest())out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
 static void remove(Context c,Model m)throws IOException{File f=path(c,m),part=new File(f.getPath()+".part");if((f.exists()&&!f.delete())||(part.exists()&&!part.delete()))throw new IOException("Não foi possível remover o modelo.");c.getSharedPreferences("ai-model-checks",0).edit().remove(m.file).apply();}
}
